parameters.jsCode:
const input = $input.first().json;

const languageMap = {
  'English':   { language: 'en', locale: 'en-US' },
  '日本語':     { language: 'ja', locale: 'ja-JP' },
  'Español':   { language: 'es', locale: 'es-ES' },
  'Français':  { language: 'fr', locale: 'fr-FR' },
  'Deutsch':   { language: 'de', locale: 'de-DE' },
  'Italiano':  { language: 'it', locale: 'it-IT' },
  'Português': { language: 'pt', locale: 'pt-PT' },
  '한국어':      { language: 'ko', locale: 'ko-KR' },
  '中文':       { language: 'zh', locale: 'zh-CN' },
};

const selectedLanguage = input['Language / 言語'];
const normalized = languageMap[selectedLanguage];

if (!normalized) {
  throw new Error(`Unsupported language: ${selectedLanguage}`);
}

return [
  {
    json: {
      ...input,

      preferred_language: normalized.language,
      preferred_locale: normalized.locale,

      language_display_name: selectedLanguage,

      session_started_at: input.submittedAt,
    },
  },
];

