parameters.jsCode:
const answer = $input.first().json;
const locale = $('Normalize Locale').first().json;

const lang = locale.preferred_language || 'en';

const maps = {
  ja: {
    pace: {
      'ゆったり楽しみたい': 'relaxed',
      'ほどよく回りたい': 'balanced',
      'できるだけたくさん回りたい': 'active'
    },
    style: {
      '定番スポット中心': 'classic',
      '定番と穴場をバランスよく': 'balanced',
      '穴場・ローカル体験中心': 'local',
      'AIにおまかせ': 'ai_decide'
    },
    budget: {
      '節約重視': 'budget',
      'バランス重視': 'balanced',
      '体験にはお金をかけたい': 'experience',
      '快適さ・質を重視': 'comfort'
    },
    labels: {
      pace: '旅行のペース',
      style: '好きな旅行スタイル',
      budget: '普段の予算スタイル'
    }
  },

  en: {
    pace: {
      'Relaxed': 'relaxed',
      'Balanced': 'balanced',
      'See as much as possible': 'active'
    },
    style: {
      'Classic highlights': 'classic',
      'Balance of highlights and hidden gems': 'balanced',
      'Hidden gems and local experiences': 'local',
      'Let AI decide': 'ai_decide'
    },
    budget: {
      'Budget-conscious': 'budget',
      'Balanced': 'balanced',
      'Spend more on experiences': 'experience',
      'Prioritize comfort and quality': 'comfort'
    },
    labels: {
      pace: 'Travel pace',
      style: 'Preferred travel style',
      budget: 'Usual budget style'
    }
  }
};

const config = maps[lang];

if (!config) {
  throw new Error(
    `Travel style normalization is not configured for language: ${lang}`
  );
}

const paceRaw = answer[config.labels.pace];
const styleRaw = answer[config.labels.style];
const budgetRaw = answer[config.labels.budget];

const travelPace = config.pace[paceRaw];
const travelStyle = config.style[styleRaw];
const budgetStyle = config.budget[budgetRaw];

if (!travelPace || !travelStyle || !budgetStyle) {
  throw new Error(
    `Could not normalize travel style answers for language: ${lang}`
  );
}

return [
  {
    json: {
      preferred_language: lang,
      preferred_locale: locale.preferred_locale,

      email: answer.email ?? null,

      travel_pace: travelPace,

      travel_pace: travelPace,
      travel_style: travelStyle,
      budget_style: budgetStyle,

      profile_session_started_at: locale.session_started_at,
      profile_updated_at: answer.submittedAt
    }
  }
];

