parameters.jsCode:
const input = $json;

const lang =
  $('Normalize Locale').first().json.preferred_language || 'en';

const profile =
  $('Prepare Travel Profile Storage').first().json;

// Form内部では全言語共通のfieldNameを使用
const origin =
  String(input.origin || '').trim();

const destinationText =
  String(input.destinations || '').trim();

const startDate =
  String(input.start_date || '').trim();

const endDate =
  String(input.end_date || '').trim();

const primaryPurpose =
  String(input.primary_purpose || '').trim();

// 将来的な複数目的地にも対応
const destinations = destinationText
  .split(/\n|;/)
  .map(value => value.trim())
  .filter(Boolean);

// 旅行日数
let tripDays = null;

if (startDate && endDate) {
  const start = new Date(`${startDate}T00:00:00Z`);
  const end = new Date(`${endDate}T00:00:00Z`);

  if (
    !Number.isNaN(start.getTime()) &&
    !Number.isNaN(end.getTime())
  ) {
    tripDays =
      Math.floor(
        (end.getTime() - start.getTime()) /
        86400000
      ) + 1;
  }
}

// 入力チェック
let validationError = null;

if (!origin) {
  validationError = 'ORIGIN_REQUIRED';
} else if (destinations.length === 0) {
  validationError = 'DESTINATION_REQUIRED';
} else if (!startDate) {
  validationError = 'START_DATE_REQUIRED';
} else if (!endDate) {
  validationError = 'END_DATE_REQUIRED';
} else if (tripDays === null || tripDays < 1) {
  validationError = 'INVALID_DATE_RANGE';
} else if (!primaryPurpose) {
  validationError = 'PRIMARY_PURPOSE_REQUIRED';
}

return [
  {
    json: {
      profile_key:
        profile.profile_key || 'default',

      preferred_language:
        profile.preferred_language || lang,

      preferred_locale:
        profile.preferred_locale || 'en-US',

      origin,

      destinations,

      start_date: startDate,
      end_date: endDate,
      trip_days: tripDays,

      primary_purpose: primaryPurpose,

      trip_basics_valid:
        validationError === null,

      trip_basics_validation_error:
        validationError,

      trip_session_started_at:
        input.submittedAt || new Date().toISOString()
    }
  }
];

const input = $json;

let raw = input.text;

if (typeof raw !== 'string' || !raw.trim()) {
  throw new Error(
    'FEASIBILITY_REQUIREMENTS_EMPTY_RESPONSE'
  );
}

// 念のためMarkdownコードフェンスにも対応
raw = raw
  .trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(raw);
} catch (error) {
  throw new Error(
    `FEASIBILITY_REQUIREMENTS_INVALID_JSON: ${error.message}`
  );
}

const allowedRouteScopes = [
  'local',
  'domestic',
  'international',
  'mixed'
];

const allowedComplexities = [
  'low',
  'medium',
  'high'
];

if (
  !allowedRouteScopes.includes(parsed.route_scope)
) {
  throw new Error(
    'FEASIBILITY_REQUIREMENTS_INVALID_ROUTE_SCOPE'
  );
}

if (
  !allowedComplexities.includes(parsed.complexity)
) {
  throw new Error(
    'FEASIBILITY_REQUIREMENTS_INVALID_COMPLEXITY'
  );
}

const booleanFields = [
  'research_required',
  'transport_research_required',
  'international_research_required',
  'timezone_research_required',
  'border_research_required',
  'schedule_research_required'
];

for (const field of booleanFields) {
  if (typeof parsed[field] !== 'boolean') {
    throw new Error(
      `FEASIBILITY_REQUIREMENTS_INVALID_${field.toUpperCase()}`
    );
  }
}

if (!Array.isArray(parsed.checks)) {
  throw new Error(
    'FEASIBILITY_REQUIREMENTS_INVALID_CHECKS'
  );
}

const checks = parsed.checks.map(
  (check, index) => {
    if (
      !check ||
      typeof check.type !== 'string' ||
      typeof check.from !== 'string' ||
      typeof check.to !== 'string' ||
      typeof check.reason !== 'string'
    ) {
      throw new Error(
        `FEASIBILITY_REQUIREMENTS_INVALID_CHECK_${index}`
      );
    }

    return {
      type: check.type.trim(),
      from: check.from.trim(),
      to: check.to.trim(),
      reason: check.reason.trim()
    };
  }
);

if (
  !Array.isArray(parsed.critical_constraints)
) {
  throw new Error(
    'FEASIBILITY_REQUIREMENTS_INVALID_CRITICAL_CONSTRAINTS'
  );
}

if (
  !Array.isArray(parsed.research_notes)
) {
  throw new Error(
    'FEASIBILITY_REQUIREMENTS_INVALID_RESEARCH_NOTES'
  );
}

return [
  {
    json: {
      route_scope:
        parsed.route_scope,

      complexity:
        parsed.complexity,

      research_required:
        parsed.research_required,

      transport_research_required:
        parsed.transport_research_required,

      international_research_required:
        parsed.international_research_required,

      timezone_research_required:
        parsed.timezone_research_required,

      border_research_required:
        parsed.border_research_required,

      schedule_research_required:
        parsed.schedule_research_required,

      checks,

      critical_constraints:
        parsed.critical_constraints
          .map(String)
          .map(v => v.trim())
          .filter(Boolean),

      research_notes:
        parsed.research_notes
          .map(String)
          .map(v => v.trim())
          .filter(Boolean),

      requirements_valid: true
    }
  }
];

const input = $json;

const checks = Array.isArray(input.checks)
  ? input.checks
  : [];

// Feasibility Gateで優先的に確認するもの
const hardPatterns = [
  /transit/i,
  /transport/i,
  /route/i,
  /duration/i,
  /travel_time/i,
  /flight/i,
  /train/i,
  /rail/i,
  /ferry/i,
  /border/i,
  /visa/i,
  /entry/i,
  /timezone/i,
  /time_zone/i,
  /international/i
];

// 詳細プラン作成時に確認すればよいもの
const softPatterns = [
  /accommodation/i,
  /hotel/i,
  /amenit/i,
  /restaurant/i,
  /food/i,
  /attraction/i,
  /sightseeing/i,
  /crowd/i,
  /congestion/i,
  /weather/i,
  /activity/i
];

const hardChecks = [];
const softChecks = [];
const otherChecks = [];

for (const check of checks) {
  const searchable = [
    check.type,
    check.reason
  ]
    .filter(Boolean)
    .join(' ');

  const isHard =
    hardPatterns.some(pattern =>
      pattern.test(searchable)
    );

  const isSoft =
    softPatterns.some(pattern =>
      pattern.test(searchable)
    );

  // Hardを優先する
  if (isHard) {
    hardChecks.push(check);
  } else if (isSoft) {
    softChecks.push(check);
  } else {
    otherChecks.push(check);
  }
}

// AIの表現揺れで重要項目を落とさないため、
// 未分類項目も調査候補として保持する
const researchChecks = [
  ...hardChecks,
  ...otherChecks
];

const hardResearchRequired =
  input.transport_research_required === true ||
  input.international_research_required === true ||
  input.timezone_research_required === true ||
  input.border_research_required === true ||
  input.schedule_research_required === true ||
  researchChecks.length > 0;

return [
