const data = $input.first().json;

const startDate =
  $('Prepare Feasibility Request').first().json.trip.start_date || '';

const checks =
  Array.isArray(data.checks)
    ? data.checks
    : [];

return checks
  .filter(check =>
    check.external_verification_required === true &&
    check.verification_query
  )
  .map((check, index) => ({
    json: {
      transit_search_index: index,

      check_type:
        check.type,

      from:
        check.from,

      to:
        check.to,

      verification_reason:
        check.verification_reason,

      verification_query:
        check.verification_query,

      search_query:
        [
          check.verification_query,
          startDate
        ]
          .filter(Boolean)
          .join(' '),

      preferred_language:
        data.preferred_language || 'en',

      preferred_locale:
        data.preferred_locale || 'en-US',

      route_scope:
        data.route_scope || null
    }
  }));

const input = $input.first().json;

let rawText =
  input?.content?.parts?.[0]?.text ??
  input?.text ??
  '';

let parsed = null;
let parseError = null;

try {
  if (typeof rawText === 'string') {
    const cleaned = rawText
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim();

    parsed = JSON.parse(cleaned);
  } else if (
    rawText &&
    typeof rawText === 'object'
  ) {
    parsed = rawText;
  }
} catch (error) {
  parseError = error.message;
}

if (!parsed) {
  return [
    {
      json: {
        itinerary_version: 1,
        parse_success: false,
        parse_error:
          parseError ||
          'Unable to parse generated itinerary',
        raw_text: rawText
      }
    }
  ];
}

return [
  {
    json: {
      ...parsed,
      parse_success: true,
      parse_error: null
    }
  }
];

const itinerary = $input.first().json;

const laterRechecks = Array.isArray(itinerary.later_rechecks)
  ? itinerary.later_rechecks
  : [];

const tripDates = Array.isArray(itinerary.days)
  ? itinerary.days
      .map(day => day.date)
      .filter(Boolean)
  : [];

const tripStartDate =
  tripDates.length > 0
    ? tripDates[0]
    : null;

const tripEndDate =
  tripDates.length > 0
    ? tripDates[tripDates.length - 1]
    : null;

return [
  {
    json: {
      ...itinerary,

      recheck_plan: {
        required:
          laterRechecks.length > 0,

        trip_start_date:
          tripStartDate,

        trip_end_date:
          tripEndDate,

        items:
          laterRechecks,

        pre_trip_recheck: {
          enabled: true,
          timing: "day_before",
          targets: [
            "weather",
            "transport_disruptions",
            "traffic_congestion",
            "facility_hours",
            "temporary_closures"
          ]
        }
      }
    }
  }
];

const input = $input.first().json;

const {
  recheck_plan: extractedRecheckPlan,
  ...itinerary
} = input;

const tripStartDate =
  itinerary.recheck_plan?.trip_start_date ??
  itinerary.days?.[0]?.date ??
  null;

const tripEndDate =
  itinerary.recheck_plan?.trip_end_date ??
  itinerary.days?.[itinerary.days.length - 1]?.date ??
  null;

const createdAt = new Date().toISOString();

const tripId = [
  'trip',
  tripStartDate || 'unknown',
  Date.now().toString(36)
].join('_');

return [
  {
    json: {
      trip_id: tripId,

      status: 'planned',

      trip_start_date: tripStartDate,
      trip_end_date: tripEndDate,

      language:
        itinerary.language ?? 'ja',

      email:
        $('Normalize Travel Style').item.json.email ?? null,

      itinerary_version:
        itinerary.itinerary_version ?? 1,

      itinerary,

recheck_plan:
  extractedRecheckPlan ?? {
          required: false,
          pre_trip_recheck: {
            enabled: false
          }
        },

      created_at: createdAt,
      updated_at: createdAt
    }
  }
];

const saved = $input.first().json;

let itinerary = null;
let recheckPlan = null;

try {
  itinerary =
    typeof saved.itinerary_json === 'string'
      ? JSON.parse(saved.itinerary_json)
      : saved.itinerary_json ?? null;
} catch (error) {
  throw new Error(
    `Failed to parse itinerary_json: ${error.message}`
  );
}

try {
  recheckPlan =
    typeof saved.recheck_plan_json === 'string'
      ? JSON.parse(saved.recheck_plan_json)
      : saved.recheck_plan_json ?? null;
} catch (error) {
  throw new Error(
    `Failed to parse recheck_plan_json: ${error.message}`
  );
}

if (!itinerary) {
  throw new Error('Saved itinerary is missing');
}

return [
  {
    json: {
      trip_id: saved.trip_id,
      status: saved.status,
      trip_start_date: saved.trip_start_date,
      trip_end_date: saved.trip_end_date,
      language: saved.language,
      email: saved.email ?? null,
      itinerary_version: saved.itinerary_version,

      itinerary,

      recheck_plan: recheckPlan,

      record_id: saved.id ?? null,
      created_at: saved.createdAt ?? null,
      updated_at: saved.updatedAt ?? null
    }
  }
];

