const items = $input.all();

// Schedule Triggerを動かしているn8n側の日付を基準にする
// 日付比較だけを行うため YYYY-MM-DD に正規化
const now = new Date();

function toDateOnly(date) {
  return new Date(
    date.getFullYear(),
    date.getMonth(),
    date.getDate()
  );
}

const today = toDateOnly(now);

const results = [];

for (const item of items) {
  const trip = item.json;

  let recheckPlan;

  try {
    recheckPlan =
      typeof trip.recheck_plan_json === 'string'
        ? JSON.parse(trip.recheck_plan_json)
        : trip.recheck_plan_json;
  } catch {
    continue;
  }

  // 再チェック不要なら対象外
  if (!recheckPlan?.required) {
    continue;
  }

  // 出発前再チェックが無効なら対象外
  if (!recheckPlan?.pre_trip_recheck?.enabled) {
    continue;
  }

  const startDateText =
    recheckPlan.trip_start_date ||
    trip.trip_start_date;

  if (!startDateText) {
    continue;
  }

    // 同じ itinerary version の再チェックが完了済みなら二重実行しない
  const currentVersion =
    Number(trip.itinerary_version);

  const completedVersion =
    trip.recheck_completed_version == null
      ? null
      : Number(trip.recheck_completed_version);

  if (
    completedVersion !== null &&
    Number.isFinite(currentVersion) &&
    Number.isFinite(completedVersion) &&
    currentVersion === completedVersion
  ) {
    continue;
  }

  const [year, month, day] =
    startDateText.split('-').map(Number);

  const tripStartDate =
    new Date(year, month - 1, day);

  if (Number.isNaN(tripStartDate.getTime())) {
    continue;
  }

  const millisecondsPerDay =
    24 * 60 * 60 * 1000;

  const daysUntilTrip =
    Math.round(
      (tripStartDate.getTime() - today.getTime()) /
      millisecondsPerDay
    );

  // 現在は day_before のみ対応
  const timing =
    recheckPlan.pre_trip_recheck.timing;

  const shouldRecheck =
    timing === 'day_before' &&
    daysUntilTrip === 1;

  if (!shouldRecheck) {
    continue;
  }

  results.push({
    json: {
      ...trip,

      recheck_plan: recheckPlan,

      recheck_context: {
        checked_date:
          [
            today.getFullYear(),
            String(today.getMonth() + 1).padStart(2, '0'),
            String(today.getDate()).padStart(2, '0')
          ].join('-'),

        trip_start_date: startDateText,

        days_until_trip: daysUntilTrip,

        timing,

        targets:
          recheckPlan.pre_trip_recheck.targets || []
      }
    }
  });
}

return results;

