function extractJson(text) {
  if (typeof text !== 'string') {
    return text;
  }

  let cleaned = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  // まず、そのままJSONとして解析
  try {
    return JSON.parse(cleaned);
  } catch {}

  // JSONの前後に余分な文章が付いた場合、
  // 最初の { から対応する最後の } までを抽出
  const firstBrace = cleaned.indexOf('{');

  if (firstBrace === -1) {
    throw new Error('JSON object not found');
  }

  let depth = 0;
  let inString = false;
  let escaped = false;

  for (
    let i = firstBrace;
    i < cleaned.length;
    i++
  ) {
    const char = cleaned[i];

    if (escaped) {
      escaped = false;
      continue;
    }

    if (char === '\\' && inString) {
      escaped = true;
      continue;
    }

    if (char === '"') {
      inString = !inString;
      continue;
    }

    if (inString) {
      continue;
    }

    if (char === '{') {
      depth++;
    }

    if (char === '}') {
      depth--;

      if (depth === 0) {
        const jsonText =
          cleaned.slice(firstBrace, i + 1);

        return JSON.parse(jsonText);
      }
    }
  }

  throw new Error(
    'Complete JSON object not found'
  );
}

