    typeof aiOutput?.text === 'string'
  ) {
    rawText =
      aiOutput.text;
  } else if (
    typeof aiOutput?.output === 'string'
  ) {
    rawText =
      aiOutput.output;
  }

  try {
    const result = extractJson(rawText);

    const finalStatus =
      [
        'no_change',
        'action_required',
        'change_required',
        'uncertain',
      ].includes(result.final_status)
        ? result.final_status
        : 'uncertain';

    const itineraryChangeRequired =
      result.itinerary_change_required === true ||
      finalStatus === 'change_required';

    const travelerActionRequired =
      result.traveler_action_required === true ||
      finalStatus === 'action_required';

