function extractJson(value) {
  if (value && typeof value === 'object') {
    return value;
  }

  if (typeof value !== 'string') {
    throw new Error('Gemini output is not a string or object');
  }

  let text = value
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  // まず全体をそのままJSONとして解析
  try {
    return JSON.parse(text);
  } catch (_) {}

  // 最初の完全なJSONオブジェクトだけを抽出
  const start = text.indexOf('{');

  if (start === -1) {
    throw new Error('JSON object not found');
  }

  let depth = 0;
  let inString = false;
  let escaped = false;

  for (let i = start; i < text.length; i++) {
    const char = text[i];

    if (escaped) {
      escaped = false;
      continue;
    }

    if (char === '\\' && inString) {
      escaped = true;
      continue;
    }

    if (char === '"') {
      inString = !inString;
      continue;
    }

    if (inString) {
      continue;
    }

    if (char === '{') {
      depth++;
    } else if (char === '}') {
      depth--;

      if (depth === 0) {
        return JSON.parse(
          text.slice(start, i + 1)
        );
      }
    }
  }

  throw new Error('Complete JSON object not found');
}

