        display_success: false,
        display_error: error.message,
        research_type: 'rebuilt_itinerary_display',
      },
    };
  }

  const language =
    data.language ||
    itinerary.language ||
    'ja';

  const isJapanese =
    language === 'ja';

  const days =
    Array.isArray(itinerary.days)
      ? itinerary.days
      : [];

  const changesMade =
    Array.isArray(itinerary.changes_made)
      ? itinerary.changes_made
      : [];

  const remainingUncertainties =
    Array.isArray(itinerary.remaining_uncertainties)
      ? itinerary.remaining_uncertainties
      : [];

  const escapeHtml = (value) =>
    String(value ?? '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');

  const formatList = (values) => {
    if (!values.length) {
      return '';
    }

    return `
      <ul>
        ${values
          .map(
            (value) =>
              `<li>${escapeHtml(
                typeof value === 'string'
                  ? value
                  : JSON.stringify(value)
              )}</li>`
          )
          .join('')}
      </ul>
    `;
  };

  const formatChanges = (values) => {
    if (!values.length) {
      return '';
    }

    return `
      <ul>
        ${values
          .map((value) => {
            if (typeof value === 'string') {
              return `<li>${escapeHtml(value)}</li>`;
            }

            const original =
              value.original || '';

            const updated =
              value.updated || '';

            const reason =
              value.reason || '';

            return `
              <li style="margin-bottom:12px;">
                ${
                  original
                    ? `<div>${escapeHtml(original)}</div>`
                    : ''
                }
                ${
                  updated
                    ? `<div>→ ${escapeHtml(updated)}</div>`
                    : ''
                }
                ${
                  reason
                    ? `<div>${isJapanese ? '理由：' : 'Reason: '}${escapeHtml(reason)}</div>`
                    : ''
                }
              </li>
            `;
          })
          .join('')}
      </ul>
    `;
  };

  const dayHtml = days
    .map((day, index) => {
      const activities =
        Array.isArray(day.activities)
          ? day.activities
          : Array.isArray(day.schedule)
            ? day.schedule
            : [];

      const activitiesHtml = activities
        .map((activity) => {
          if (typeof activity === 'string') {
            return `<li>${escapeHtml(activity)}</li>`;
          }

          const time =
            activity.time ||
            activity.start_time ||
            '';

          const title =
            activity.title ||
            activity.activity ||
            activity.name ||
            activity.place ||
            activity.location ||
            '';

          const description =
            activity.description ||
            activity.details ||
            activity.note ||
            activity.notes ||
            '';

          return `
            <li style="margin-bottom:10px;">
              ${
                time
                  ? `<strong>${escapeHtml(time)}</strong> `
                  : ''
              }
              ${escapeHtml(title)}
              ${
                description
                  ? `<div>${escapeHtml(description)}</div>`
                  : ''
              }
            </li>
          `;
        })
        .join('');

      return `
        <div style="margin-top:24px;">
          <h3>
            ${
              isJapanese
                ? `${index + 1}日目`
                : `Day ${index + 1}`
            }
            ${
              day.date
                ? ` - ${escapeHtml(day.date)}`
                : ''
            }
          </h3>

          ${
            day.summary
              ? `<p>${escapeHtml(day.summary)}</p>`
              : ''
          }

          ${
            activitiesHtml
              ? `<ul>${activitiesHtml}</ul>`
              : ''
          }
        </div>
      `;
    })
    .join('');

  const displayHtml = `
    <div>
      <h2>
        ${
          isJapanese
            ? '更新後の旅行プラン'
            : 'Updated Travel Itinerary'
        }
      </h2>

      <p>
        ${
          isJapanese
            ? `旅程をVersion ${data.itinerary_version}へ更新しました。`
            : `Your itinerary has been updated to Version ${data.itinerary_version}.`
        }
      </p>

      ${
        itinerary.rebuild_summary
          ? `
            <h3>
              ${
                isJapanese
                  ? '変更内容'
                  : 'Update Summary'
              }
            </h3>
            <p>${escapeHtml(itinerary.rebuild_summary)}</p>
          `
          : ''
      }

      ${
        changesMade.length
          ? `
            <h3>
              ${
                isJapanese
                  ? '今回の変更点'
                  : 'Changes Made'
              }
            </h3>
            ${formatChanges(changesMade)}
          `
          : ''
      }

      ${dayHtml}

      ${
        remainingUncertainties.length
          ? `
            <h3>
              ${
                isJapanese
                  ? '出発前に再確認してください'
                  : 'Please Recheck Before Departure'
              }
            </h3>
            ${formatList(remainingUncertainties)}
          `
          : ''
      }
    </div>
  `;

  return {
    json: {
      ...data,

      language,

      itinerary_version:
        data.itinerary_version,

      rebuilt_itinerary: itinerary,

      rebuild_summary:
        itinerary.rebuild_summary ||
        data.rebuild_summary ||
        '',

      changes_made:
        changesMade,

      remaining_uncertainties:
        remainingUncertainties,

      display_html: displayHtml,

      display_success: true,
      display_error: null,

      research_type:
        'rebuilt_itinerary_display',
    },
  };
});

